func:
if (!msg.payload.uplink_message) {
    return null;  // kein Uplink (z.B. Join-Event, Downlink-ACK) — ignorieren
}
try {
    var raw = Buffer.from(msg.payload.uplink_message.frm_payload, 'base64');
    var t = raw[0];
    msg.eventType = t;
    msg.devEui = msg.topic.split('/')[3];

    if (t === 1) {
        msg.flowData = {
            timeinterval: ((raw[2]<<24)|(raw[3]<<16)|(raw[4]<<8)|raw[5]) >>> 0,
            flowCl: (raw[6]<<8)|raw[7]
        };
    } else if (t === 2) {
        msg.schedule = {
            onH:raw[2], onM:raw[3], onS:raw[4],
            offH:raw[5], offM:raw[6], offS:raw[7],
            cntrCl:(raw[8]<<8)|raw[9],
            maxPI:(raw[10]<<8)|raw[11]
        };
    } else if (t === 4) {
        msg.wateringStart = { status: 'watering_started' };
    } else if (t === 5) {
        msg.alarmPulses = (raw[2]<<8)|raw[3];
    } else if (t === 7) {
        msg.wateringEnd = {
            totalFlowCl: (raw[2]<<8)|raw[3],
            totalTimeMs: ((raw[4]<<24)|(raw[5]<<16)|(raw[6]<<8)|raw[7]) >>> 0
        };
    }
    return msg;
} catch(e) {
    node.error('decode error: ' + e.message, msg);
    return null;
}

msg.payload = {
    flow_cl:         msg.flowData.flowCl,
    flow_liter:      parseFloat((msg.flowData.flowCl / 100.0).toFixed(2)),
    timeinterval_ms: msg.flowData.timeinterval
};
msg.tags = { node: 'garden-node-1' };
return msg;

msg.payload = {
    on_hour: msg.schedule.onH, on_min: msg.schedule.onM, on_sec: msg.schedule.onS,
    off_hour: msg.schedule.offH, off_min: msg.schedule.offM, off_sec: msg.schedule.offS,
    cntr_cl:    msg.schedule.cntrCl,
    cntr_liter: parseFloat((msg.schedule.cntrCl / 100.0).toFixed(2)),
    max_pulses_per_interval: msg.schedule.maxPI
};
msg.tags = { node: 'garden-node-1' };
return msg;

var lPerMin = (msg.alarmPulses / 595.0 * 12).toFixed(2);
msg.payload = {chatId:5846653852, type:'message',
    content:'🚨 ALARM: Leckage!\nNode: garden-node-1\nDurchfluss: '+lPerMin+' L/min\nVentil geschlossen.'};
return msg;

var liter = (msg.wateringEnd.totalFlowCl / 100.0).toFixed(2);
var m = Math.round(msg.wateringEnd.totalTimeMs / 60000);
msg.payload = {chatId:5846653852, type:'message',
    content:'✅ Bewässerung beendet\nNode: garden-node-1\nMenge: '+liter+' Liter\nDauer: '+m+' min'};
msg.influxPayload = [{measurement:'garden_irrigation', tags:{node:'garden-node-1'},
    fields:{
        total_cl:    msg.wateringEnd.totalFlowCl,
        total_liter: parseFloat(liter),
        duration_ms:  msg.wateringEnd.totalTimeMs,
        duration_min: parseFloat((msg.wateringEnd.totalTimeMs/60000).toFixed(2))
    }}];
return [msg, msg];

msg.payload = {
    total_cl: msg.wateringEnd.totalFlowCl,
    total_liter: parseFloat((msg.wateringEnd.totalFlowCl / 100.0).toFixed(2)),
    duration_ms: msg.wateringEnd.totalTimeMs,
    duration_min: parseFloat((msg.wateringEnd.totalTimeMs / 60000).toFixed(2))
};
msg.tags = { node: 'garden-node-1' };
return msg;

const p = msg.payload;
const buf = Buffer.alloc(7);
buf[0] = 1;
buf[1] = p.on_hour  !== undefined ? p.on_hour  : 20;
buf[2] = p.on_min   !== undefined ? p.on_min   : 0;
buf[3] = p.on_sec   !== undefined ? p.on_sec   : 0;
buf[4] = p.off_hour !== undefined ? p.off_hour : 20;
buf[5] = p.off_min  !== undefined ? p.off_min  : 30;
buf[6] = p.off_sec  !== undefined ? p.off_sec  : 0;
msg.topic   = "v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push";
msg.payload = JSON.stringify({ downlinks: [{ f_port: 1, frm_payload: buf.toString("base64"), priority: "NORMAL" }] });
return msg;

const cl = (msg.payload.cntr_value_cl !== undefined) ? msg.payload.cntr_value_cl : 300;
const buf = Buffer.alloc(3);
buf[0] = 4;
buf[1] = (cl >> 8) & 0xFF;
buf[2] =  cl       & 0xFF;
msg.topic   = "v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push";
msg.payload = JSON.stringify({ downlinks: [{ f_port: 1, frm_payload: buf.toString("base64"), priority: "NORMAL" }] });
return msg;

const mp = msg.payload.max_pulses || 3000;
const buf = Buffer.alloc(3);
buf[0] = 6;
buf[1] = (mp >> 8) & 0xFF;
buf[2] =  mp       & 0xFF;
msg.topic   = "v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push";
msg.payload = JSON.stringify({ downlinks: [{ f_port: 1, frm_payload: buf.toString("base64"), priority: "NORMAL" }] });
return msg;

if (msg.payload && msg.payload.length > 0) {
    msg.soilMoisture = parseFloat(msg.payload[0]._value) || 0;
} else {
    node.warn('Kein Bodensensor-Wert in letzten 24h — überspringe Bewässerung');
    msg.soilMoisture = 100; // kein Wert = sicher überspringen
}
node.warn('Bodenfeuchte: ' + msg.soilMoisture.toFixed(1) + '%');
return msg;

var rainToday = 0;
if (msg.payload && msg.payload.length > 0) {
    rainToday = parseFloat(msg.payload[0]._value) || 0;
}
msg.rainToday = rainToday;
node.warn('Regen heute: ' + rainToday.toFixed(1) + ' mm');
msg.url = 'https://api.open-meteo.com/v1/forecast'
    + '?latitude=48.6792063554118&longitude=8.90313130163122'
    + '&hourly=precipitation&forecast_days=2&timezone=Europe%2FBerlin';
return msg;

// ── Schwellwerte (anpassbar) ───────────────────────────────────────
var SOIL_THRESH        = 25;   // % — unter diesem Wert Bewässerung nötig
var RAIN_TODAY_THRESH  = 3;    // mm — darüber heute bereits genug Regen
var RAIN_FORE_THRESH   = 5;    // mm — darüber in 12h Regen erwartet
// ──────────────────────────────────────────────────────────────────

// Nächste 12h Niederschlag aus Open-Meteo-Stundenwerten
var forecast12h = 0;
try {
    var hourly = msg.payload.hourly;
    var times  = hourly.time;
    var precip = hourly.precipitation;
    var now     = new Date();
    var curHour = now.getHours();
    var todayStr = now.toISOString().split('T')[0];
    var count = 0;
    for (var i = 0; i < times.length && count < 12; i++) {
        var parts = times[i].split('T');
        var d = parts[0];
        var h = parseInt(parts[1].split(':')[0]);
        if ((d === todayStr && h >= curHour) || d > todayStr) {
            forecast12h += precip[i];
            count++;
        }
    }
    forecast12h = parseFloat(forecast12h.toFixed(1));
} catch(e) {
    node.warn('Wetter-Parse-Fehler: ' + e.message);
}

var soil      = msg.soilMoisture;
var rainToday = msg.rainToday || 0;
var cntr = 0;
var skipReason = '';

if (soil >= SOIL_THRESH) {
    skipReason = 'Bodenfeuchte ausreichend (' + soil.toFixed(1) + '%)';
} else if (rainToday >= RAIN_TODAY_THRESH) {
    skipReason = 'Regen heute: ' + rainToday.toFixed(1) + ' mm';
} else if (forecast12h >= RAIN_FORE_THRESH) {
    skipReason = 'Regen vorhergesagt: ' + forecast12h.toFixed(1) + ' mm';
} else {
    // Menge in Centilitern: sehr trocken (<15%) → 600 cL (6 L), linear bis 200 cL
    if (soil < 15) {
        cntr = 1000;
    } else {
        cntr = Math.round(1000 - 400 * (soil - 15) / (SOIL_THRESH - 15));
        cntr = Math.max(200, Math.min(600, cntr));
    }
}

msg.cntr        = cntr;
flow.set('cntr', cntr);  // für 19:30-Retry gespeichert
msg.forecast12h = forecast12h;
msg.decision    = cntr > 0 ? 'BEREGNEN' : 'ÜBERSPRINGEN';
msg.skipReason  = skipReason;

node.warn('Entscheidung: ' + msg.decision + ' cntr=' + cntr + ' cL (' + (cntr/100).toFixed(1) + ' L)'
    + ' soil=' + soil.toFixed(1) + '% regen=' + rainToday.toFixed(1)
    + 'mm vorhersage=' + forecast12h + 'mm');

return [msg, msg];

// Max Gesamtmenge: Event 4 — Wert in Centilitern
// cntr = 0 → kein Bewässern (Ventil bleibt geschlossen)
// cntr > 0 → Bewässern bis diese Menge erreicht ist
var cntr = msg.cntr || 0;

var bytes = [4, (cntr >> 8) & 0xFF, cntr & 0xFF];
msg.topic = 'v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push';
msg.payload = JSON.stringify({downlinks:[{f_port:1,
    frm_payload: Buffer.from(bytes).toString('base64'), priority:'NORMAL'}]});
return msg;

var icon = msg.cntr > 0 ? '\u{1F4A7}' : '\u2600\uFE0F';
var text = icon + ' Gartenbewässerung ' + msg.decision + '\n'
    + 'Bodenfeuchte: ' + msg.soilMoisture.toFixed(1) + '%\n'
    + 'Regen heute: '  + msg.rainToday.toFixed(1) + ' mm\n'
    + 'Vorhersage 12h: ' + msg.forecast12h.toFixed(1) + ' mm';
if (msg.cntr > 0) {
    text += '\nMenge: ' + (msg.cntr / 100).toFixed(1) + ' L';
} else {
    text += '\nGrund: ' + msg.skipReason;
}
msg.payload = {chatId: 5846653852, type: 'message', content: text};
return msg;

var d = msg.payload;
var yr = d.year;
var buf = Buffer.from([
    3,
    (yr >> 8) & 0xFF, yr & 0xFF,
    d.month, d.day, d.hour, d.min, d.sec
]);
msg.topic = "v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push";
msg.payload = JSON.stringify({
    downlinks: [{
        f_port: 1,
        frm_payload: buf.toString("base64"),
        priority: "NORMAL"
    }]
});
return msg;

// 19:30 Retry: cntr-Wert von 18:00 nochmal senden
var cntr = flow.get('cntr');
if (cntr === undefined || cntr === null) {
    node.warn('19:30 Retry: kein cntr gespeichert — übersprungen');
    return null;
}
var bytes = [4, (cntr >> 8) & 0xFF, cntr & 0xFF];
msg.topic = 'v3/hs-garden@ttn/devices/eui-70b3d57ed0051782/down/push';
msg.payload = JSON.stringify({downlinks:[{f_port:1,
    frm_payload: Buffer.from(bytes).toString('base64'), priority:'NORMAL'}]});
return msg;
